-- GASP dataset subscription (snapshot; Subscription). snapshot rows on month starts, month ends and the period bounds shifted back by one, three, six and twelve months
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.subscription (
  auto_renewed BOOLEAN,
  contract_end DATE,
  contract_start DATE,
  customer_id VARCHAR(1000),
  forecast_renewal_amount DECIMAL(18, 6),
  plan_id VARCHAR(1000),
  mrr DECIMAL(18, 6),
  mrr_end DECIMAL(18, 6),
  mrr_start DECIMAL(18, 6),
  renewal_amount DECIMAL(18, 6),
  renewal_complete_date DATE,
  renewal_notified_on_time BOOLEAN,
  renewal_trigger_date DATE,
  renewed BOOLEAN,
  segment VARCHAR(1000),
  snapshot_date DATE,
  subscription_id VARCHAR(1000),
  subscription_status VARCHAR(1000)
);
